import json
from collections import Counter

def task_func(json_str, top_n=10):
    # Parse the JSON string into a Python dictionary
    data = json.loads(json_str)

    # Initialize a Counter to count URLs
    url_counter = Counter()

    # Define a regular expression pattern for URLs
    url_pattern = re.compile(r'https?://[^\s/$.?#].[^\s]*')

    # Traverse the dictionary to find URLs
    def find_urls(obj):
        if isinstance(obj, dict):
            for key, value in obj.items():
                find_urls(key)
                find_urls(value)
        elif isinstance(obj, list):
            for item in obj:
                find_urls(item)
        elif isinstance(obj, str):
            for match in url_pattern.finditer(obj):
                url = match.group()
                url_counter[url] += 1

    find_urls(data)

    # Get the top N URLs with the highest counts
    top_urls = url_counter.most_common(top_n)

    return dict(top_urls)

