def task_func(directory, string):
    # Find all JSON files in the directory and its subdirectories
    json_files = glob(f"{directory}/**/*.json", recursive=True)

    # List to store paths of files containing the string in their JSON data
    result = []

    # Iterate over each JSON file
    for file in json_files:
        try:
            # Open the JSON file
            with open(file, 'r') as f:
                # Load the JSON data
                data = json.load(f)

                # Check if the string is present in the JSON data structure
                if isinstance(data, dict):
                    if string in data or string in str(data):
                        result.append(file)
                elif isinstance(data, list):
                    for item in data:
                        if isinstance(item, dict) and string in item or string in str(item):
                            result.append(file)
                            break  # No need to continue checking the rest of the list
        except json.JSONDecodeError:
            # If there's an error decoding the JSON, skip the file
            continue

    return result

