        # Parse the JSON string into a dictionary
        data = json.loads(json_str)

        # Define a function to recursively normalize the dictionary
        def normalize_dict(d):
            for key, value in d.items():
                if isinstance(value, dict):
                    normalize_dict(value)
                elif isinstance(value, (list, str)):
                    if isinstance(value, list):
                        d[key] = [double_value(v) for v in value]
                    elif isinstance(value, str):
                        d[key] = double_value(re.findall(r'\d+', value))
            return d

        # Helper function to double the value if it's a number
        def double_value(value):
            if isinstance(value, (int, float)):
                return value * 2
            return value

        # Normalize the dictionary
        normalized_data = normalize_dict(data)

        # Convert the dictionary to a Pandas DataFrame
        df = pd.DataFrame(normalized_data)

        return df
    except json.JSONDecodeError:
        return pd.DataFrame()

